#include <stdio.h>
#include <stdlib.h>
#include <inttypes.h>

static void exit_with_msg(const char *msg) {
    puts(msg);
    exit(0);
}

static long long parse_ll(const char *s) {
    char *endptr = NULL;
    long long v = strtoll(s, &endptr, 10);
    if (endptr == s || *endptr != '\0') {
        exit_with_msg("BAD_INPUT");
    }
    return v;
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        puts("NO_INPUT");
        return 0;
    }

    long long base = parse_ll(argv[1]);
    long long exp  = parse_ll(argv[2]);
    long long mod  = parse_ll(argv[3]);

    if (mod < 1) {
        puts("BAD_MODULUS");
        return 0;
    }
    if (mod > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (exp < 0) {
        puts("NEGATIVE_EXPONENT");
        return 0;
    }

    /* bring base into [0, mod-1] */
    base %= mod;
    if (base < 0) base += mod;

    long long result = 1 % mod; // handles mod == 1 correctly
    while (exp > 0) {
        if (exp & 1LL) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }

    printf("result=%" PRId64 "\n", result);
    return 0;
}
